INSERT INTO public.site_faqs (page_slug, question, answer, category, sort_order, published) VALUES
('home','What is MunchReach?','MunchReach is a cold outreach platform. You build campaigns, automate follow-ups, manage every reply in one inbox, and track results from a single workspace.','general',0,true),
('home','Do I need my own email infrastructure?','No. Sending is fully managed, so there is nothing technical to configure. Connect a domain, add your sending identity, and launch.','general',1,true),
('home','How fast can I launch my first campaign?','Most teams launch in under 30 minutes: create a workspace, import leads, write the first email, add follow-up steps, and schedule the send.','getting-started',2,true),
('home','Does MunchReach stop follow-ups when someone replies?','Yes. The moment a prospect replies, their remaining follow-up steps stop automatically and the conversation moves to your unified inbox.','general',3,true),
('home','Can my whole team work in the same account?','Yes. Invite teammates with roles for campaigns, inbox, analytics, or read-only access, and keep clients separated in their own workspaces.','teams',4,true),
('campaigns','How many follow-up steps can a campaign have?','As many as you need. Each step has its own delay, subject, and body, and you can pause or edit steps while the campaign is running.','campaigns',0,true),
('campaigns','Can I personalise emails for each lead?','Yes. Use lead fields such as first name, company, and role directly in the subject and body, plus AI-assisted variants when you want more variety.','campaigns',1,true),
('campaigns','How do sending limits and schedules work?','You set a daily volume, delay between sends, sending days, and sending window. Campaigns respect those limits automatically across every connected email account.','sending',2,true),
('campaigns','Can I test a campaign before launching?','Yes. Send test emails to yourself or teammates to review rendering, personalisation, and links before any lead is contacted.','campaigns',3,true),
('campaigns','What happens to bounced or unsubscribed leads?','They are suppressed automatically and excluded from this and future campaigns in the workspace.','deliverability',4,true),
('follow-ups','When do follow-ups stop?','Follow-ups stop as soon as a lead replies, unsubscribes, bounces, or is manually removed from the sequence.','automation',0,true),
('follow-ups','Can I set different delays per step?','Yes. Every step has its own delay in days, so you can space early touches closely and later touches further apart.','automation',1,true),
('follow-ups','Are follow-ups sent from the same email account?','Yes. Follow-ups stay in the same thread from the same sending account, which keeps conversations natural and improves replies.','sending',2,true),
('follow-ups','Can I edit a sequence after launch?','Yes. Edit copy, add steps, or pause the sequence at any time. Changes apply to the steps that have not been sent yet.','automation',3,true),
('unified-inbox','Do replies really land inside MunchReach?','Yes. Replies are captured and threaded with the original campaign, so you can read and respond without leaving the app.','inbox',0,true),
('unified-inbox','Can I reply directly from the inbox?','Yes. Replies are sent from the original sending account and stay in the same thread as the prospect sees it.','inbox',1,true),
('unified-inbox','Can I organise conversations with my team?','Assign conversations to teammates, add internal notes, and mark outcomes such as interested, not now, or won.','teams',2,true),
('unified-inbox','Do I see lead context next to the conversation?','Yes. Each thread shows the lead record, campaign history, and previous activity so anyone on the team can pick it up.','inbox',3,true),
('warmup','What does warmup actually do?','It gradually builds natural sending activity on your email accounts and monitors health signals so your volume ramps up safely.','deliverability',0,true),
('warmup','How long should I warm up before sending campaigns?','Two to three weeks is typical for a new address. MunchReach shows a readiness signal per account so you know when to start.','deliverability',1,true),
('warmup','Can warmup run while campaigns are active?','Yes. Warmup keeps running alongside campaigns and shares the same daily limits, so accounts are never overloaded.','deliverability',2,true),
('warmup','What happens if an account looks unhealthy?','You get an alert on the account, and you can pause it in one click while you fix the underlying issue.','deliverability',3,true),
('crm','Is the CRM built for outreach?','Yes. Conversations move through outbound-specific stages, so your pipeline reflects real replies instead of manual data entry.','crm',0,true),
('crm','Do leads move through stages automatically?','Replies create and advance pipeline cards automatically, and you can drag cards between stages whenever you want.','crm',1,true),
('crm','Can I customise the pipeline stages?','Yes. Rename, reorder, add, or remove stages per workspace to match how your team sells.','crm',2,true),
('crm','Can I keep notes and tasks on a lead?','Every lead supports notes, tasks, and a full activity timeline of emails, replies, and stage changes.','crm',3,true),
('analytics','Which metrics does MunchReach track?','Sent, delivered, opens, clicks, replies, bounces, and unsubscribes — by campaign, by step, and by sending account.','analytics',0,true),
('analytics','Can I compare campaigns and email accounts?','Yes. Break results down by campaign, step variant, or sending account to see what is driving replies.','analytics',1,true),
('analytics','How current is the data?','Metrics update continuously as events arrive, so dashboards reflect activity within minutes.','analytics',2,true),
('analytics','Can I export reports?','Yes. Export the underlying data to CSV for your own reporting or client updates.','analytics',3,true),
('email-accounts','How many email accounts can I connect?','Connect as many as your plan allows. Campaigns can rotate across accounts to spread volume safely.','sending',0,true),
('email-accounts','Do I need to configure DNS records?','You add a domain and follow a guided setup that shows exactly which records to add at your DNS host, with live verification.','domains',1,true),
('email-accounts','Can I pause a single account?','Yes. Pause or disable any account instantly. Campaigns continue on the remaining healthy accounts.','sending',2,true),
('email-accounts','What if verification fails?','The setup screen shows which record is missing or mismatched, so you can correct it and re-check without support.','domains',3,true),
('workspaces','What is a workspace for?','A workspace holds one brand or client: its domains, email accounts, leads, campaigns, inbox, and reporting stay fully separated.','teams',0,true),
('workspaces','Can I run multiple clients from one account?','Yes. Create a workspace per client and switch between them without signing out or mixing data.','teams',1,true),
('workspaces','What roles are available?','Owner, admin, campaign manager, inbox manager, analyst, and client viewer, so each teammate sees only what they need.','teams',2,true),
('workspaces','Can clients get read-only access?','Yes. Invite them as a client viewer to share results without giving access to campaigns or settings.','teams',3,true),
('templates','Are the templates ready to send?','Yes. Each template is a complete sequence you can import into a campaign and edit in your own voice.','templates',0,true),
('templates','Can I save my own templates?','Yes. Save any campaign or step as a reusable template for your team.','templates',1,true),
('templates','Do templates support personalisation fields?','Templates use the same lead fields as campaigns, so personalisation carries over when you import them.','templates',2,true);